function minimumArrayLength(nums) {
  let smallest = nums[0];
  for (const value of nums) {
    smallest = Math.min(smallest, value);
  }

  let count = 0;
  for (const value of nums) {
    if (value % smallest !== 0) {
      return 1;
    }
    if (value === smallest) {
      count++;
    }
  }
  return Math.ceil(count / 2);
}

