function minimumArrayLength(nums) {
  const memo = new Map();
  const best = (values) => {
    const key = values.join(',');
    if (memo.has(key)) return memo.get(key);
    let answer = values.length;
    for (let i = 0; i < values.length; i++) {
      for (let j = 0; j < values.length; j++) {
        if (i === j || values[i] === 0 || values[j] === 0) continue;
        const next = values.filter((_, index) => index !== i && index !== j);
        next.push(values[i] % values[j]);
        next.sort((x, y) => x - y);
        answer = Math.min(answer, best(next));
      }
    }
    memo.set(key, answer);
    return answer;
  };
  return best([...nums].sort((x, y) => x - y));
}

