  if (size === 'small') {
    const n = int(1, 6);
    if (rand() < 0.6) {
      const base = int(1, 4);
      return [Array.from({ length: n }, () => base * int(1, 4))];
    }
    return [Array.from({ length: n }, () => int(1, 12))];
  }
  const n = int(1500, 2000);
  const mode = rand();
  if (mode < 0.3) return [Array.from({ length: n }, () => int(1, 1e9))];
  const base = int(1, 1000000);
  const count = int(1, n - 1);
  const nums = [];
  for (let i = 0; i < n; i++) nums.push(i < count ? base : base * int(2, Math.floor(1e9 / base)));
  if (mode < 0.5) nums[int(count, n - 1)] = base * int(2, Math.floor(1e9 / base) - 1) + int(1, base - 1);
  for (let i = n - 1; i > 0; i--) { const r = int(0, i); [nums[i], nums[r]] = [nums[r], nums[i]]; }
  return [nums];
}
